import ScrumBoard from "@/components/ScrumBoard";
import { prisma } from "src/lib/prisma"; 
import { ScrumTask, ColumnId } from "@/src/types/scrum";

export default async function ScrumboardPage() {
  try {
    // Sadece Scrum Board kolonlarında olan görevleri çekiyoruz (Filtre eklendi)
    const tasksRaw = await prisma.task.findMany({
      where: {
        status: {
          in: ['BACKLOG', 'SPRINT', 'TODO', 'IN_PROGRESS', 'DONE']
        }
      }
    }) || [];
    
    const formattedTasks: ScrumTask[] = tasksRaw.map((t) => ({
      id: t.id,
      content: t.title,
      columnId: t.status as ColumnId,
    }));

    return (
      <div className="min-h-screen bg-[#070B24] p-8">
        <div className="mb-10 border-b border-teal-500/10 pb-6">
          <h1 className="text-4xl font-black text-white italic uppercase tracking-tighter">System Board</h1>
          <p className="text-teal-500/50 text-[10px] font-bold tracking-[0.4em] mt-2 uppercase italic">Database Online</p>
        </div>
        <ScrumBoard initialTasks={formattedTasks} />
      </div>
    );
  } catch (error) {
    console.error("Board Error:", error);
    return (
      <div className="min-h-screen bg-[#070B24] p-10 text-center">
        <h2 className="text-red-500 font-bold uppercase tracking-widest">Database Sync Error</h2>
        <p className="text-white/40 text-xs mt-2 italic">Please check your MariaDB connection.</p>
      </div>
    );
  }
}